<?php
declare(strict_types=1);
defined('NU_ROOT') || exit;

/**
 * Every key nuBuilder Next keeps in $_SESSION, with what it holds (code review R10). Use $_SESSION[NuSess::X] – never a key written
 * as text (dev/tests/run.php checks core/, pages/ and index.php). A new key = a constant here with its line of description.
 */
final class NuSess
{
	public const AUTH                = 'nu_auth';   // the signed-in user {id, login, globeadmin, fp, via …} (NuAuth)
	public const SESS                = 'nu_sess';   // row id of zzzzsys_nunext_session for this session (NuSessions)
	public const CSRF                = 'nu_csrf';   // secret of the form token (nu_csrf_secret)
	public const LANG                = 'nu_lang';   // language of the interface, 'en' / 'de' … (nu_lang)
	public const LANG_VARIANT        = 'nu_lang_variant';   // language variant en-GB / en-US / de-CH … (nu_lang_variant)
	public const LANG_CARRIED        = 'nu_lang_carried';   // the language came from the session before sign-in, not picked (NuAuth::applyLanguage)
	public const TWOFA               = 'nu_2fa';   // pending second factor after the password {user, at, tries …} (NuTwoFa, NuAuth)
	public const TOTP_SETUP          = 'nu_totp_setup';   // secret of an authenticator app being set up (NuSecurity)
	public const PASSKEY             = 'nu_passkey';   // open passkey ceremonies by kind, one use (NuPasskey)
	public const REAUTH_NEXT         = 'nu_reauth_next';   // page to return to after the password was confirmed again (NuSecurity::requireRecentAuth)
	public const LOGIN_NEXT          = 'nu_login_next';   // page to return to after the sign-in (NuAuth)
	public const AUTOLOGIN_PENDING   = 'nu_autologin_pending';   // nuBuilder Forte auto-login ?u=… waiting for the second factor (pages/nuautologin.php)
	public const WEAK_ADMIN          = 'nu_weak_admin';   // the globeadmin signed in with a weak password – warning on every page (index.php)
	public const PW_SOON             = 'nu_pw_soon';   // the password expires soon – one notice (NuPwPolicy)
	public const PW_GA               = 'nu_pw_ga';   // reminder to the globeadmin about the password policy (NuPwPolicy)
	public const PW_REASON           = 'nu_pw_reason';   // why a password change is forced: leaked / expired (NuPwPolicy, pages/nupassword.php)
	public const FORGOT              = 'nu_forgot';   // rate limit of the forgot-password page (pages/nuforgot.php)
	public const IMP                 = 'nu_imp';   // acting as another user {user, mode, back, role …} (NuImpersonate)
	public const HASH_COOKIES        = 'nu_hashcookies';   // nuBuilder Forte's hash cookies set by form code (NuHashCookies)
	public const HASH_SESSION        = 'nu_hash_session';   // value of #SESSION_ID# when there is no nuBuilder Forte session (NuHash)
	public const FORTE_DATA          = 'nubuilder_session_data';   // nuBuilder Forte's own session data – read only, in Forte's session (NuSharedLogin)
	public const PROPS               = 'nu_ps';   // form properties (nuSetProperty) per page scope (NuProps)
	public const TRAIL               = 'nu_bt';   // breadcrumb trails of form pages (NuTrail)
	public const DISTINCT_VALUES     = 'nu_dv';   // distinct values of list filters, cached (NuBrowse)
	public const ROW_DETAILS_FOUND   = 'nu_rd_found';   // child tables found for row details, cached (NuRowDetails)
	public const JSON_DATA           = 'nu_json_data';   // nuSetJSONData() values of form code (nuphp_compat)
	public const URL_PARAMS          = 'nu_url_params';   // GET parameters of the last unknown route for nuGetURLParams() (index.php)
	public const REPORT_RUNS         = 'nu_report_runs';   // recent report runs of this session (NuReport)
	public const FORM_PREVIEW        = 'nu_form_preview';   // form drafts shown instead of the live form (NuFormDraft)
	public const LIST_VIEWS          = 'nu_listviews';   // chosen list views of demo visitors (NuListView)
	public const HOME_VIEW           = 'nu_home_view';   // personal start page view of demo visitors (NuHome)
	public const HOME_HOOK           = 'nu_home_hook';   // cached result of the start page hook nu_home (NuHomeHook)
	public const STATUS_WARN         = 'nu_status_warn';   // count of status warnings on the start page, cached (NuHome)
	public const TUT_OFFER           = 'nu_tut_offer';   // offer of the tutorial after the set-up (NuHome, NuSetupWizard)
	public const TUT_IDS             = 'nu_tut_ids';   // lesson ids of the tutorial, cached (NuTutorial)
	public const RECENT              = 'nu_recent';   // recently used pages of demo visitors (NuSidebar)
	public const SIDEBAR             = 'nu_sidebar';   // side bar on / off of demo visitors (NuSidebar)
	public const SIDEBAR_PIN         = 'nu_sidebar_pin';   // side bar pinned (NuSidebar)
	public const THEME               = 'nu_theme';   // theme picked by a demo visitor (NuTheme)
	public const THEME_DRAFT         = 'nu_theme_draft';   // theme being edited, for the preview frame (NuTheme)
	public const GETTING_READY       = 'nu_gr';   // summary of the Getting ready checklist, cached (NuReady)
	public const GETTING_READY_HIDE  = 'nu_gr_hide';   // Getting ready hidden until the next sign-in (NuReady)
	public const NOTIFY              = 'nu_ntf';   // notification centre: seen ids / counts (NuNotify)
	public const NOTIFY_FORM         = 'nu_ntf_form';   // notification being edited after a failed save (pages/nunotifications.php)
	public const PAGE                = 'nu_page';   // own session store of each custom page, by form code (NuPage)
	public const PAGE_DEP            = 'nu_page_dep';   // deprecated custom page APIs already logged (NuPage)
	public const PAGE_DRAFT          = 'nu_page_draft';   // custom pages shown as their draft (NuPageVersion)
	public const PROJECT_FORM        = 'nu_prj_form';   // project form input after a failed save (pages/nuprojects.php)
	public const FLASH               = 'nu_flash';   // messages for the next page (nu_flash)
	public const VENDOR              = 'nu_vendor';   // database tool / File Manager sign-ins handed over (NuVendor)
	public const VENDOR_OPEN         = 'nu_vendor_open';   // one-time links that open a database tool in an app window (NuVendor)
	public const UPDATE              = 'nu_update';   // checked update package waiting for Install (pages/nuupdate.php, NuAutoUpdate)
	public const UPDATE_FOLDER       = 'nu_upd_folder';   // package picked from the _update folder (pages/nuupdate.php)
	public const BACKUP_ONCE         = 'nu_backup_once';   // one-time token of Back up now (pages/nuupdate.php)
	public const LIBPACK_TEST        = 'nu_lp_test';   // results of the library pack self-tests (pages/nuupdate.php)
	public const LIBPACK             = 'nu_libpack';   // built library packs to download (pages/nulibpack.php)
	public const SCHEMA              = 'nu_schema';   // own tables checked for this version (NuSchema)
	public const DB_READY            = 'nu_db_ready';   // the database is set up: version|host|db (NuDbState)
	public const DB_RESET            = 'nu_dbreset';   // checked file of Reset database (NuDbReset)
	public const DB_RESET_FRESH      = 'nu_dbreset_fresh';   // fresh installation from a package waiting for its last step (NuDbReset)
	public const DB_SETUP_AUTH       = 'nu_dbs_auth';   // the database set-up page was opened with the setup token (pages/nudbsetup.php)
	public const DB_SETUP_DONE       = 'nu_dbs_done';   // result of the database set-up (pages/nudbsetup.php)
	public const INSTALL             = 'nu_install';   // answers of the installer's steps (pages/nuinstall.php)
	public const SETUP_WIZARD        = 'nu_setup_wiz';   // answers of the setup wizard (NuSetupWizard)
	public const SETUP_WIZARD_MANUAL = 'nu_setup_wiz_manual';   // the setup wizard was opened by hand (NuSetupWizard)
	public const SETUP_WIZARD_SEEN   = 'nu_setup_wiz_seen';   // the setup wizard was shown once this session (NuSetupWizard, index.php)
	public const SETUP_TZ            = 'nu_setup_tz';   // time zone chosen in the set-up before it is stored (nu_timezone)
	public const SAMPLE_PW           = 'nu_sample_pw';   // passwords of the sample users, shown once (NuSample)
	public const SAMPLE_PW_SET       = 'nu_sample_pw_set';   // passwords of a sample set, shown once (NuSample)
	public const SELFTEST            = 'nu_selftest';   // results of the last self-test run (NuSelfTest)
	public const BASE_SEEN           = 'nu_base_seen';   // the base address was checked once (NuSecurity)
	public const DASH_CACHE          = 'nu_dash_cache';   // results of dashboard widgets, cached (NuDashboard)
	public const AI_UNLOCKED         = 'nu_ai_unlocked';   // AI providers unlocked with their password (NuAiProvider)
	public const AI_TRIES            = 'nu_ai_tries';   // failed unlock attempts per AI provider (NuAiProvider)
	public const AI_TEST             = 'nu_aip_test';   // result of an AI provider's Test (pages/nuaiproviders.php)
	public const API_SECRET          = 'nu_api_secret';   // new API client secret, shown once (pages/nuapiclients.php)
	public const WEBHOOK_SECRET      = 'nu_wh_secret';   // new webhook secret, shown once (pages/nuwebhooks.php)
	public const WEBHOOK_TEST        = 'nu_wh_test';   // result of a webhook's Send test (pages/nuwebhooks.php)
	public const HEALTH_KEY          = 'nu_health_key';   // new health check key, shown once (pages/nusettings.php)
	public const LOGIN_LINK          = 'nu_ltok_link';   // new one-time login link, shown once (pages/nuuser.php)
	public const PW_RESET_LINK       = 'nu_pwr_link';   // password reset link made by an administrator, shown once (pages/nuuser.php)
	public const WELCOME_PREVIEW     = 'nu_welcome_pv';   // welcome e-mail shown in the preview frame (pages/nuuser.php)
	public const MAIL_OAUTH          = 'nunext_mail_oauth';   // state of the SMTP OAuth consent (NuMailOAuth)
	public const SSO                 = 'nunext_sso';   // state / nonce / PKCE of a single sign-on (NuSso)
	public const SSO_TEST            = 'nunext_sso_test';   // result of the single sign-on Test (NuSso)
	public const PROJECT             = 'nu_project';   // project being worked on (NuProject)
	public const RECORD_OK           = 'nu_record_ok';   // records that passed the record check (NuRecord)
	public const RECENT_LAST         = 'nu_recent_last';   // last recorded page of the recent list (NuSidebar)
	public const HOME_HIDE_UNDO      = 'nu_home_hide_undo';   // last hidden start page tile, for Undo (NuSidebar)
	public const TUTORIAL            = 'nu_tutorial';   // tutorial progress of demo visitors (NuTutorial)
	public const IMPORT              = 'nu_import';   // state of a running data import (NuImport)
}
